"""Probabilistic and classic data structures implemented from scratch."""

from __future__ import annotations

import hashlib
import math
from typing import Any, Generic, TypeVar

T = TypeVar("T")
K = TypeVar("K")
V = TypeVar("V")

# ---------------------------------------------------------------------------
# HyperLogLog — cardinality estimation
# ---------------------------------------------------------------------------

class HyperLogLog:
    """Probabilistic data structure for estimating the number of distinct elements.

    Uses the HyperLogLog algorithm with harmonic-mean correction.
    Accuracy is controlled by *precision* (number of register bits):
    standard error ≈ 1.04 / sqrt(2**precision).

    Supports ``add`` and ``count`` — not stack-like operations.
    """

    def __init__(self, precision: int = 14) -> None:
        if not 4 <= precision <= 16:
            raise ValueError("precision must be between 4 and 16")
        self.precision = precision
        self.num_registers = 1 << precision
        self.registers: list[int] = [0] * self.num_registers

    def _hash(self, element: Any) -> int:
        digest = hashlib.sha256(str(element).encode()).digest()
        return int.from_bytes(digest, "big")

    def add(self, element: Any) -> None:
        """Add an element to the sketch."""
        h = self._hash(element)
        register_index = h >> (256 - self.precision)
        remaining = h & ((1 << (256 - self.precision)) - 1)
        leading_zeros = self._count_leading_zeros(remaining, 256 - self.precision) + 1
        self.registers[register_index] = max(self.registers[register_index], leading_zeros)

    def count(self) -> int:
        """Estimate the number of distinct elements added."""
        alpha = self._alpha()
        raw = alpha * self.num_registers**2 / sum(2.0**-r for r in self.registers)

        if raw <= 2.5 * self.num_registers:
            zeros = self.registers.count(0)
            if zeros:
                return int(self.num_registers * math.log(self.num_registers / zeros))
        return int(raw)

    def merge(self, other: HyperLogLog) -> HyperLogLog:
        """Return a new HyperLogLog that is the union of *self* and *other*."""
        if self.precision != other.precision:
            raise ValueError("cannot merge sketches with different precision")
        merged = HyperLogLog(self.precision)
        merged.registers = [max(a, b) for a, b in zip(self.registers, other.registers)]
        return merged

    def __len__(self) -> int:
        return self.count()

    def __contains__(self, element: Any) -> bool:
        raise NotImplementedError(
            "HyperLogLog does not support membership testing; use count() instead"
        )

    # -- helpers --------------------------------------------------------------

    @staticmethod
    def _count_leading_zeros(value: int, width: int) -> int:
        if value == 0:
            return width
        return width - value.bit_length()

    def _alpha(self) -> float:
        if self.num_registers == 16:
            return 0.673
        if self.num_registers == 32:
            return 0.697
        if self.num_registers == 64:
            return 0.709
        return 0.7213 / (1 + 1.079 / self.num_registers)


# ---------------------------------------------------------------------------
# Stack — LIFO
# ---------------------------------------------------------------------------

class Stack(Generic[T]):
    """LIFO stack with O(1) push, pop, and peek.

    Backed by a dynamic array (Python list).
    """

    def __init__(self) -> None:
        self._data: list[T] = []

    def push(self, item: T) -> None:
        """Push *item* onto the top of the stack."""
        self._data.append(item)

    def pop(self) -> T:
        """Remove and return the top item.

        Raises
        ------
        IndexError
            If the stack is empty.
        """
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._data.pop()

    def peek(self) -> T:
        """Return the top item without removing it.

        Raises
        ------
        IndexError
            If the stack is empty.
        """
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self._data[-1]

    def is_empty(self) -> bool:
        """Return ``True`` if the stack has no items."""
        return len(self._data) == 0

    def __len__(self) -> int:
        return len(self._data)

    def __repr__(self) -> str:
        return f"Stack({self._data})"


# ---------------------------------------------------------------------------
# HashMap — O(1) average put / get / remove
# ---------------------------------------------------------------------------

class HashMap(Generic[K, V]):
    """Hash map with separate chaining, O(1) average-case operations.

    Automatically resizes when the load factor exceeds 0.75.
    """

    _INITIAL_CAPACITY = 16
    _LOAD_FACTOR_THRESHOLD = 0.75

    def __init__(self) -> None:
        self._capacity = self._INITIAL_CAPACITY
        self._buckets: list[list[tuple[K, V]]] = [[] for _ in range(self._capacity)]
        self._size = 0

    # -- public API -----------------------------------------------------------

    def put(self, key: K, value: V) -> None:
        """Insert or update the *key* → *value* mapping."""
        if self._load_factor() >= self._LOAD_FACTOR_THRESHOLD:
            self._resize(self._capacity * 2)

        bucket = self._bucket_for(key)
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self._size += 1

    def get(self, key: K, default: V | None = None) -> V | None:
        """Return the value for *key*, or *default* if not found."""
        for k, v in self._bucket_for(key):
            if k == key:
                return v
        return default

    def remove(self, key: K) -> V:
        """Remove and return the value for *key*.

        Raises
        ------
        KeyError
            If *key* is not in the map.
        """
        bucket = self._bucket_for(key)
        for i, (k, v) in enumerate(bucket):
            if k == key:
                del bucket[i]
                self._size -= 1
                return v
        raise KeyError(key)

    def contains(self, key: K) -> bool:
        """Return ``True`` if *key* is in the map."""
        return any(k == key for k, _ in self._bucket_for(key))

    def __len__(self) -> int:
        return self._size

    def __contains__(self, key: K) -> bool:
        return self.contains(key)

    def __repr__(self) -> str:
        items = ", ".join(f"{k!r}: {v!r}" for bucket in self._buckets for k, v in bucket)
        return f"HashMap({{{items}}})"

    # -- internals ------------------------------------------------------------

    def _bucket_for(self, key: K) -> list[tuple[K, V]]:
        return self._buckets[hash(key) % self._capacity]

    def _load_factor(self) -> float:
        return self._size / self._capacity

    def _resize(self, new_capacity: int) -> None:
        old_buckets = self._buckets
        self._capacity = new_capacity
        self._buckets = [[] for _ in range(self._capacity)]
        self._size = 0
        for bucket in old_buckets:
            for key, value in bucket:
                self.put(key, value)
